-- 84 nouvelles fiches minéraux (Apprendre) : caractéristiques sans photo, dont de nombreuses espèces et variétés françaises.
-- Une fiche déjà présente (même nom ou même slug) n'est pas modifiée.
on conflict do nothing;

-- Lussatite : fiche existante restée vide ; seuls les champs vides sont complétés.
update public.minerals set
  formula = coalesce(formula, 'SiO₂·nH₂O'),
  crystal_system = coalesce(crystal_system, 'Amorphe'),
  chemical_class = coalesce(chemical_class, 'Oxydes et hydroxydes'),
  hardness = coalesce(hardness, 5.5),
  hardness_max = coalesce(hardness_max, 6.0),
  density = coalesce(density, 2.0),
  density_max = coalesce(density_max, 2.1),
  colors = coalesce(colors, array['blanc laiteux','blanc bleuté','incolore']::text[]),
  luster = coalesce(luster, 'soyeux à cireux'),
  cleavage = coalesce(cleavage, 'aucun'),
  streak = coalesce(streak, 'blanc'),
  transparency = coalesce(transparency, 'translucide'),
  fracture = coalesce(fracture, 'conchoïdale à fibreuse'),
  fluorescence = coalesce(fluorescence, 'Parfois verte aux UV (traces d''uranium).'),
  habit = coalesce(habit, 'Croûtes mamelonnées à structure fibreuse, enduits dans les fissures.'),
  formation = coalesce(formation, 'Fissures de roches volcaniques et sédimentaires ; localité type : Lussat (Puy-de-Dôme).'),
  etymology = coalesce(etymology, 'De Lussat (Puy-de-Dôme), où Ernest Mallard la décrivit en 1890.'),
  varieties = coalesce(varieties, 'Variété fibreuse d''opale (opale-CT, silice mal cristallisée de type cristobalite-tridymite).'),
  confusions = coalesce(confusions, 'Calcédoine : plus dure et plus dense. Hyalite : limpide, en gouttelettes.'),
  description = coalesce(description, 'Opale fibreuse décrite en Auvergne, à Lussat : une silice à mi-chemin entre l''opale et la cristobalite.')
where slug = 'lussatite';
