insert into public.minerals (name, slug, formula, crystal_system, chemical_class, hardness, hardness_max, density, density_max, colors, luster, cleavage, streak, transparency, fracture, fluorescence, habit, formation, etymology, varieties, confusions, description, publication_status) values
  ('Annabergite', 'annabergite', 'Ni₃(AsO₄)₂·8H₂O', 'Monoclinique', 'Phosphates, arséniates et vanadates', 1.5, 2.5, 3.0, 3.1, array['vert pomme','vert pâle','blanc grisâtre']::text[], 'vitreux à terreux', 'parfait', 'vert pâle à blanc', 'transparent à translucide', 'irrégulière', null, 'Croûtes et enduits pulvérulents ; rares cristaux prismatiques aplatis, aiguilles en éventail.', 'Zone d''oxydation des gisements de nickel et cobalt arséniés.', 'D''Annaberg (Saxe, Allemagne).', 'Cabrérite (riche en magnésium).', 'Érythrite : même structure, mais rose violacé (série continue entre les deux).', 'Arséniate de nickel vert pomme, appelé « fleur de nickel » par les anciens mineurs : sa présence signalait du minerai de nickel en profondeur.', 'published'),
  ('Antimoine', 'antimoine', 'Sb', 'Trigonal', 'Éléments natifs', 3.0, 3.5, 6.6, 6.7, array['blanc d''étain','gris argent']::text[], 'métallique', 'parfait (basal)', 'gris', 'opaque', 'irrégulière', null, 'Masses lamellaires ou granulaires, réniformes ; cristaux très rares.', 'Filons hydrothermaux à antimoine et arsenic, souvent avec stibine, arsenic natif et valentinite.', 'Du latin médiéval antimonium, d''origine discutée.', null, 'Arsenic natif : plus léger, ternit rapidement en noir. Allemontite (Sb-As) : intermédiaire, analyse nécessaire.', 'Élément natif rare, cassant, à l''éclat métallique blanc d''étain et au clivage basal parfait.', 'published'),
  ('Arsenic', 'arsenic', 'As', 'Trigonal', 'Éléments natifs', 3.5, 3.5, 5.6, 5.8, array['gris étain','noir (ternissure)']::text[], 'métallique, terne après ternissure', 'parfait (basal)', 'gris étain', 'opaque', 'irrégulière', null, 'Masses réniformes et concrétions en couches concentriques (« testacées ») ; cristaux rares.', 'Filons hydrothermaux à argent, cobalt et nickel (Sainte-Marie-aux-Mines, Alsace).', 'Du grec arsenikon, désignant l''orpiment.', null, 'Antimoine natif : plus dense, ne noircit pas aussi vite. Une odeur d''ail au choc ou à la chauffe trahit l''arsenic (à éviter : toxique).', 'Élément natif gris qui noircit à l''air ; toxique, il se manipule avec précaution et en se lavant les mains.', 'published'),
  ('Bénitoïte', 'benitoite', 'BaTiSi₃O₉', 'Hexagonal', 'Silicates (cyclosilicates)', 6.0, 6.5, 3.6, 3.7, array['bleu saphir','bleu pâle','incolore']::text[], 'vitreux', 'indistinct', 'blanc', 'transparent à translucide', 'conchoïdale à irrégulière', 'Bleu intense aux UV courts.', 'Cristaux triangulaires (bipyramides trigonales aplaties), dans la natrolite blanche.', 'Veines hydrothermales dans des serpentinites et schistes bleus ; gisement de référence : comté de San Benito (Californie).', 'Du comté de San Benito, en Californie.', null, 'Saphir : plus dur (9). Sapphirine, cordiérite : forme cristalline différente, pas de fluorescence bleue.', 'Silicate de baryum et titane d''un bleu saphir, célèbre pour ses cristaux triangulaires et sa fluorescence bleue éclatante.', 'published'),
  ('Berthiérite', 'berthierite', 'FeSb₂S₄', 'Orthorhombique', 'Sulfures et sulfosels', 2.0, 3.0, 4.6, 4.7, array['gris acier','gris foncé, irisé']::text[], 'métallique', 'indistinct', 'gris brun', 'opaque', 'irrégulière', null, 'Masses fibreuses, aciculaires ou plumeuses ; se ternit en irisations bronze.', 'Filons hydrothermaux à antimoine, avec stibine et quartz (Massif central).', 'De Pierre Berthier (1782-1861), chimiste et ingénieur des mines français.', null, 'Stibine : clivage parfait et éclat plus vif. Jamesonite : contient du plomb, plus dense.', 'Sulfure de fer et d''antimoine gris acier, décrit en France, fréquent dans les anciennes mines d''antimoine d''Auvergne.', 'published'),
  ('Beudantite', 'beudantite', 'PbFe₃(AsO₄)(SO₄)(OH)₆', 'Trigonal', 'Phosphates, arséniates et vanadates', 3.5, 4.5, 4.0, 4.3, array['vert foncé à noir','brun','jaune']::text[], 'vitreux à résineux', 'bon (basal)', 'jaune verdâtre', 'translucide', 'irrégulière', null, 'Petits rhomboèdres pseudo-cubiques, croûtes.', 'Zone d''oxydation des gisements de plomb et fer.', 'De François Sulpice Beudant (1787-1850), minéralogiste français.', null, 'Jarosite et plumbojarosite : sans arsenic, couleur plus jaune. Ségnitite et corkite : analyse nécessaire.', 'Arséniate-sulfate de plomb et fer en petits rhomboèdres sombres, typique des chapeaux de fer.', 'published'),
  ('Borax', 'borax', 'Na₂B₄O₅(OH)₄·8H₂O', 'Monoclinique', 'Borates', 2.0, 2.5, 1.7, 1.7, array['incolore','blanc','gris']::text[], 'vitreux à résineux', 'parfait', 'blanc', 'transparent à translucide, devient opaque', 'conchoïdale', null, 'Prismes trapus courts ; se déshydrate en surface en tincalconite blanche et poudreuse.', 'Évaporites des lacs salés en climat aride (Californie, Tibet, Turquie).', 'Du persan burah, par l''arabe.', null, 'Halite et sylvite : goût salé, clivage cubique. Ulexite, kernite : autres borates, habit différent.', 'Borate de sodium des lacs salés ; ses cristaux transparents blanchissent à l''air en perdant leur eau, à conserver en boîte fermée.', 'published'),
  ('Carnotite', 'carnotite', 'K₂(UO₂)₂(VO₄)₂·3H₂O', 'Monoclinique', 'Phosphates, arséniates et vanadates', 2.0, 2.0, 4.7, 5.0, array['jaune canari','jaune verdâtre']::text[], 'terreux, nacré sur cristaux', 'parfait', 'jaune', 'opaque à translucide', 'irrégulière', 'Généralement non fluorescente (le vanadium l''éteint).', 'Enduits pulvérulents et imprégnations dans les grès ; cristaux microscopiques en plaquettes.', 'Grès uranifères et vanadifères, bois fossiles (plateau du Colorado).', 'D''Adolphe Carnot (1839-1920), chimiste et ingénieur des mines français.', null, 'Tyuyamunite : pôle calcique, analyse nécessaire. Autunite : fluorescente vert-jaune, en plaquettes.', 'Vanadate d''uranium jaune canari, minerai d''uranium et de vanadium. Radioactif : à conserver à l''écart et à manipuler peu.', 'published'),
  ('Cavansite', 'cavansite', 'Ca(VO)Si₄O₁₀·4H₂O', 'Orthorhombique', 'Silicates (phyllosilicates)', 3.0, 4.0, 2.2, 2.3, array['bleu vif','bleu vert']::text[], 'vitreux', 'bon', 'bleu clair', 'transparent à translucide', 'irrégulière', null, 'Rosettes et sphères radiées d''aiguilles bleues, souvent sur stilbite ou heulandite.', 'Cavités de basaltes avec des zéolites (région de Pune, Inde).', 'De sa composition : CAlcium, VANadium, Silicate.', null, 'Pentagonite : même composition, cristaux maclés en étoile. Chrysocolle : amorphe, sans rosettes cristallines.', 'Silicate de calcium et vanadium aux rosettes bleu électrique, très recherché dans les géodes de basalte indiennes.', 'published'),
  ('Chlorargyrite', 'chlorargyrite', 'AgCl', 'Cubique', 'Halogénures', 1.5, 2.5, 5.5, 5.6, array['incolore','gris perle','brun violacé (à la lumière)']::text[], 'résineux à adamantin, cireux', 'aucun', 'blanc', 'translucide', 'irrégulière, sectile', null, 'Croûtes cireuses, masses en « corne », cubes rares ; se coupe au couteau.', 'Zone d''oxydation des gisements d''argent en climat aride (Chili, Mexique, Australie).', 'Du grec chlôros (vert pâle) et argyros (argent).', 'Kérargyrite (« argent corné »), ancien nom.', 'Bromargyrite et iodargyrite : analyse nécessaire. Cérusite : effervescence, pas sectile.', 'Chlorure d''argent qui se coupe comme de la cire et noircit à la lumière, important minerai d''argent historique (« argent corné »).', 'published'),
  ('Colémanite', 'colemanite', 'CaB₃O₄(OH)₃·H₂O', 'Monoclinique', 'Borates', 4.5, 4.5, 2.4, 2.4, array['incolore','blanc','gris','jaunâtre']::text[], 'vitreux à adamantin', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière à subconchoïdale', 'Parfois blanc crème à jaunâtre.', 'Cristaux prismatiques trapus très brillants, géodes, nodules.', 'Gisements de borates des lacs asséchés (vallée de la Mort, Californie ; Turquie).', 'De William Tell Coleman (1824-1893), exploitant de borax californien.', null, 'Calcite : effervescence à l''acide, clivage rhomboédrique. Datolite : plus dure.', 'Borate de calcium en cristaux limpides et éclatants, l''un des principaux minerais de bore.', 'published'),
  ('Descloizite', 'descloizite', 'PbZn(VO₄)(OH)', 'Orthorhombique', 'Phosphates, arséniates et vanadates', 3.0, 3.5, 5.9, 6.2, array['brun rouge','brun noir','orange']::text[], 'gras à vitreux', 'aucun', 'orange à brun rouge', 'translucide à opaque', 'irrégulière à subconchoïdale', null, 'Petits cristaux pyramidaux ou prismatiques en druses, croûtes mamelonnées.', 'Zone d''oxydation des gisements de plomb-zinc riches en vanadium (Namibie, Zambie, Mexique).', 'D''Alfred Des Cloizeaux (1817-1897), minéralogiste français.', null, 'Mottramite : pôle cuivrifère de la série, plus verdâtre. Vanadinite : prismes hexagonaux.', 'Vanadate de plomb et zinc en druses brun rouge scintillantes, souvent associé à la vanadinite.', 'published'),
  ('Dumortiérite', 'dumortierite', 'Al₇(BO₃)(SiO₄)₃O₃', 'Orthorhombique', 'Silicates (nésosilicates)', 7.0, 8.5, 3.2, 3.4, array['bleu','violet','rose brun']::text[], 'vitreux', 'bon', 'blanc', 'translucide à opaque', 'irrégulière', 'Parfois bleu à violet faible aux UV.', 'Masses fibreuses ou en aiguilles radiées, souvent incluses dans le quartz (« quartz dumortiérite »).', 'Roches métamorphiques riches en aluminium et pegmatites ; décrite près de Lyon (Chaponost).', 'D''Eugène Dumortier (1803-1873), paléontologue lyonnais.', 'Quartz à dumortiérite (bleu).', 'Sodalite : plus tendre, veines blanches. Lazulite et lazurite : densité et habit différents.', 'Borosilicate d''aluminium bleu, décrit pour la première fois en France, près de Lyon.', 'published'),
  ('Dufrénite', 'dufrenite', 'Fe²⁺Fe³⁺₄(PO₄)₃(OH)₅·2H₂O', 'Monoclinique', 'Phosphates, arséniates et vanadates', 3.5, 4.5, 3.1, 3.3, array['vert foncé','vert olive','noir verdâtre','brun (altérée)']::text[], 'soyeux à vitreux', 'parfait', 'jaune verdâtre', 'opaque à translucide', 'irrégulière', null, 'Croûtes et boules fibroradiées, mamelons à structure fibreuse.', 'Gisements de fer oxydés et pegmatites à phosphates (Limousin).', 'D''Ours-Pierre-Armand Petit-Dufrénoy (1792-1857), minéralogiste français.', null, 'Rockbridgeite et béraunite : autres phosphates de fer, analyse nécessaire. Goethite : trait brun jaune.', 'Phosphate de fer vert sombre en boules fibreuses, classique des pegmatites et des minerais de fer phosphatés.', 'published'),
  ('Énargite', 'enargite', 'Cu₃AsS₄', 'Orthorhombique', 'Sulfures et sulfosels', 3.0, 3.0, 4.4, 4.5, array['gris acier','noir']::text[], 'métallique', 'parfait (prismatique)', 'noir grisâtre', 'opaque', 'irrégulière', null, 'Prismes striés à section pseudo-hexagonale, masses lamellaires.', 'Filons hydrothermaux de cuivre de haute sulfuration (Butte, Montana ; Pérou).', 'Du grec enargês (visible, distinct), à cause de son clivage.', null, 'Tennantite : cubique, sans clivage. Stibine : plus tendre, plus brillante.', 'Sulfoarséniure de cuivre gris acier, important minerai de cuivre dans les Andes et les Rocheuses.', 'published'),
  ('Euclase', 'euclase', 'BeAlSiO₄(OH)', 'Monoclinique', 'Silicates (nésosilicates)', 7.5, 7.5, 3.0, 3.1, array['incolore','bleu pâle','bleu vert','vert']::text[], 'vitreux', 'parfait', 'blanc', 'transparent', 'conchoïdale', null, 'Cristaux prismatiques allongés, striés.', 'Pegmatites granitiques et filons hydrothermaux (Minas Gerais, Brésil ; Zimbabwe).', 'Du grec eu (bien) et klasis (cassure), pour son clivage facile.', null, 'Béryl (aigue-marine) : prismes hexagonaux, pas de clivage net. Topaze : plus dure, orthorhombique.', 'Silicate de béryllium et aluminium, prisé pour ses cristaux bleus limpides malgré un clivage qui les rend fragiles.', 'published'),
  ('Franklinite', 'franklinite', 'ZnFe₂O₄', 'Cubique', 'Oxydes et hydroxydes', 5.5, 6.0, 5.0, 5.2, array['noir']::text[], 'métallique à submétallique', 'aucun', 'brun rouge foncé', 'opaque', 'conchoïdale à irrégulière', null, 'Octaèdres aux arêtes arrondies, grains dans la calcite.', 'Gisement de zinc métamorphisé de Franklin et Sterling Hill (New Jersey).', 'De Franklin (New Jersey, États-Unis).', null, 'Magnétite : trait noir, fortement magnétique (la franklinite l''est faiblement).', 'Oxyde de zinc et fer de la famille des spinelles, star des gisements fluorescents de Franklin.', 'published'),
  ('Haüyne', 'hauyne', 'Na₃Ca(Si₃Al₃)O₁₂(SO₄)', 'Cubique', 'Silicates (tectosilicates)', 5.5, 6.0, 2.4, 2.5, array['bleu vif','bleu ciel','blanc','gris']::text[], 'vitreux à gras', 'distinct', 'bleu très pâle à blanc', 'transparent à translucide', 'conchoïdale à irrégulière', 'Parfois orange rouge aux UV longs.', 'Petits grains arrondis et dodécaèdres dans les laves.', 'Roches volcaniques pauvres en silice : phonolites, téphrites (Eifel, Latium).', 'De René Just Haüy (1743-1822), minéralogiste français, père de la cristallographie.', null, 'Sodalite et lazurite : même groupe, souvent en masses. Saphir : bien plus dur.', 'Feldspathoïde bleu vif des laves, dédié au minéralogiste français René Just Haüy.', 'published'),
  ('Jamesonite', 'jamesonite', 'Pb₄FeSb₆S₁₄', 'Monoclinique', 'Sulfures et sulfosels', 2.5, 2.5, 5.5, 5.7, array['gris plomb','gris acier']::text[], 'métallique', 'bon (basal)', 'gris noir', 'opaque', 'irrégulière', null, 'Aiguilles et fibres capillaires en touffes (« plumosite »), masses feutrées.', 'Filons hydrothermaux plomb-antimoine à basse et moyenne température.', 'De Robert Jameson (1774-1854), minéralogiste écossais.', 'Plumosite (aiguilles capillaires, ancien nom).', 'Boulangérite : sans fer, analyse nécessaire. Stibine : plus légère, clivage parfait.', 'Sulfosel de plomb, fer et antimoine en touffes d''aiguilles fines comme des plumes.', 'published'),
  ('Kermésite', 'kermesite', 'Sb₂S₂O', 'Triclinique', 'Sulfures et sulfosels', 1.0, 1.5, 4.6, 4.7, array['rouge cerise','rouge pourpre']::text[], 'adamantin à submétallique', 'parfait', 'rouge brun', 'translucide', 'irrégulière, flexible', null, 'Aiguilles et lames rouges en gerbes, souvent sur stibine qu''elle remplace.', 'Altération de la stibine dans les gisements d''antimoine.', 'De l''arabe qirmiz (rouge cramoisi), comme « kermès ».', null, 'Réalgar : jaune orangé, sans association à la stibine. Cinabre : trait rouge vif, très dense.', 'Oxysulfure d''antimoine rouge cerise en gerbes d''aiguilles, né de l''altération de la stibine.', 'published'),
  ('Laumontite', 'laumontite', 'CaAl₂Si₄O₁₂·4H₂O', 'Monoclinique', 'Silicates (tectosilicates)', 3.5, 4.0, 2.2, 2.3, array['blanc','rosé','crème']::text[], 'vitreux, nacré sur clivage, devient terne', 'parfait', 'blanc', 'transparent, devient opaque', 'irrégulière', null, 'Prismes à terminaison oblique, en gerbes ; s''effrite à l''air en perdant de l''eau.', 'Cavités de roches volcaniques, filons hydrothermaux, fentes alpines (décrite en Bretagne, à Huelgoat).', 'De Gillet de Laumont (1747-1834), minéralogiste français.', 'Léonhardite (forme partiellement déshydratée).', 'Stilbite et heulandite : clivage nacré mais restent limpides. Orthose : plus dure.', 'Zéolite blanche qui devient crayeuse à l''air ; on la conserve parfois sous vernis ou en boîte humide.', 'published'),
  ('Legrandite', 'legrandite', 'Zn₂(AsO₄)(OH)·H₂O', 'Monoclinique', 'Phosphates, arséniates et vanadates', 4.5, 4.5, 3.9, 4.0, array['jaune vif','jaune cire','incolore']::text[], 'vitreux', 'faible', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Prismes jaunes allongés en gerbes et éventails, souvent sur limonite.', 'Zone d''oxydation des gisements de zinc arséniés (Mapimí, Mexique).', 'De Louis Legrand, ingénieur des mines belge.', null, 'Adamite : vert jaune et fluorescente. Paradamite : analyse nécessaire.', 'Arséniate de zinc en gerbes jaune soleil, l''un des fleurons de la mine Ojuela à Mapimí.', 'published'),
  ('Lépidocrocite', 'lepidocrocite', 'γ-FeO(OH)', 'Orthorhombique', 'Oxydes et hydroxydes', 5.0, 5.0, 3.9, 4.1, array['rouge','brun rouge','noir rouge']::text[], 'submétallique à adamantin', 'parfait', 'orange à brun', 'translucide en écailles', 'irrégulière', null, 'Écailles et lamelles, rosettes, inclusions rouges dans le quartz.', 'Altération des minéraux de fer, chapeaux de fer, sols ; inclusions dans le quartz et l''améthyste.', 'Du grec lepis (écaille) et krokis (fibre).', null, 'Goethite : même formule, trait brun jaune. Hématite : trait rouge.', 'Oxyhydroxyde de fer en écailles rouges ; ses inclusions colorent certains quartz « fraise ».', 'published'),
  ('Ludlamite', 'ludlamite', 'Fe₃(PO₄)₂·4H₂O', 'Monoclinique', 'Phosphates, arséniates et vanadates', 3.5, 3.5, 3.1, 3.2, array['vert pomme','vert clair','incolore']::text[], 'vitreux', 'parfait', 'blanc verdâtre', 'transparent à translucide', 'irrégulière', null, 'Cristaux tabulaires en coin, groupes.', 'Pegmatites à phosphates et filons hydrothermaux sulfurés (Bolivie, Idaho).', 'De Henry Ludlam (1824-1880), collectionneur anglais.', null, 'Vivianite : bleu vert, plus tendre, flexible. Variscite : en masses, pas en cristaux nets.', 'Phosphate de fer vert pomme, apprécié pour ses cristaux limpides en forme de coin.', 'published'),
  ('Mésolite', 'mesolite', 'Na₂Ca₂Al₆Si₉O₃₀·8H₂O', 'Monoclinique', 'Silicates (tectosilicates)', 5.0, 5.0, 2.2, 2.3, array['blanc','incolore']::text[], 'vitreux, soyeux en touffes', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Aiguilles capillaires en touffes et houppes très fines, fragiles.', 'Cavités de basaltes avec d''autres zéolites (Inde, Islande, Féroé).', 'Du grec mesos (au milieu), intermédiaire entre natrolite et scolécite.', null, 'Natrolite et scolécite : même habit, distinction par analyse. Okénite : fibres plus souples en boules.', 'Zéolite en houppes d''aiguilles soyeuses, très délicate, typique des basaltes.', 'published'),
  ('Mottramite', 'mottramite', 'PbCu(VO₄)(OH)', 'Orthorhombique', 'Phosphates, arséniates et vanadates', 3.0, 3.5, 5.7, 6.0, array['vert olive','vert jaune','brun noir']::text[], 'gras à vitreux', 'aucun', 'vert jaune', 'translucide à opaque', 'irrégulière', null, 'Croûtes drusiques, enduits veloutés, petits cristaux.', 'Zone d''oxydation des gisements de plomb-cuivre riches en vanadium (Namibie, Arizona).', 'De Mottram St Andrew (Cheshire, Angleterre).', null, 'Descloizite : pôle zincifère, plus brun rouge. Malachite : effervescence, trait vert.', 'Vanadate de plomb et cuivre en croûtes vert olive scintillantes, pendant cuivrifère de la descloizite.', 'published'),
  ('Okénite', 'okenite', 'CaSi₂O₄(OH)₂·H₂O', 'Triclinique', 'Silicates (phyllosilicates)', 4.5, 5.0, 2.2, 2.3, array['blanc','blanc bleuté','jaunâtre']::text[], 'vitreux à nacré, soyeux', 'parfait', 'blanc', 'translucide', 'irrégulière', null, 'Boules de fibres souples comme du coton, souvent sur calcédoine ou zéolites.', 'Cavités de basaltes (trapps du Deccan, Inde).', 'De Lorenz Oken (1779-1851), naturaliste allemand.', null, 'Mésolite : aiguilles rigides et cassantes. Gyrolite : en lamelles.', 'Silicate de calcium en « boules de neige » de fibres soyeuses, emblématique des géodes indiennes.', 'published'),
  ('Pectolite', 'pectolite', 'NaCa₂Si₃O₈(OH)', 'Triclinique', 'Silicates (inosilicates)', 4.5, 5.0, 2.8, 2.9, array['blanc','gris','bleu ciel (larimar)']::text[], 'vitreux à soyeux', 'parfait', 'blanc', 'translucide à opaque', 'esquilleuse', 'Parfois jaune à orange.', 'Aiguilles radiées et masses fibreuses compactes ; éclats acérés.', 'Cavités de basaltes, roches ultrabasiques ; le larimar vient de République dominicaine.', 'Du grec pêktos (compact) et lithos (pierre).', 'Larimar (bleu ciel, République dominicaine).', 'Wollastonite : pas de sodium, analyse nécessaire. Natrolite : plus légère, en prismes.', 'Silicate sodi-calcique fibreux ; sa variété bleu ciel, le larimar, est une gemme des Caraïbes. Attention aux échardes.', 'published'),
  ('Pharmacosidérite', 'pharmacosiderite', 'KFe₄(AsO₄)₃(OH)₄·6-7H₂O', 'Cubique', 'Phosphates, arséniates et vanadates', 2.5, 2.5, 2.8, 2.9, array['vert olive','vert émeraude','jaune miel','brun']::text[], 'adamantin à gras', 'imparfait', 'vert pâle à jaune', 'transparent à translucide', 'irrégulière', null, 'Petits cubes nets, souvent maclés, en druses.', 'Zone d''oxydation des gisements à arsénopyrite (Cornouailles ; nombreux gîtes français).', 'Du grec pharmakon (poison) et sidêros (fer).', null, 'Scorodite : orthorhombique, bleu vert. Fluorite : clivage octaédrique, plus dure.', 'Arséniate de fer en petits cubes verts ou miel, fréquent dans les anciennes mines à arsenic.', 'published'),
  ('Phénakite', 'phenakite', 'Be₂SiO₄', 'Trigonal', 'Silicates (nésosilicates)', 7.5, 8.0, 2.9, 3.0, array['incolore','blanc','jaune pâle','rose']::text[], 'vitreux', 'distinct', 'blanc', 'transparent à translucide', 'conchoïdale', 'Parfois bleu pâle à vert.', 'Rhomboèdres lenticulaires, prismes courts, macles en pénétration.', 'Pegmatites granitiques, greisens et micaschistes à émeraude (Oural, Brésil, Madagascar).', 'Du grec phenax (trompeur), car longtemps confondue avec le quartz.', null, 'Quartz : moins dur, plus léger, prismes striés. Topaze : clivage basal parfait.', 'Silicate de béryllium plus dur que le quartz, avec lequel on le confondait autrefois.', 'published'),
  ('Phosgénite', 'phosgenite', 'Pb₂CO₃Cl₂', 'Quadratique', 'Carbonates', 2.0, 3.0, 6.1, 6.2, array['incolore','blanc','jaune','brun']::text[], 'adamantin', 'distinct', 'blanc', 'transparent à translucide', 'conchoïdale', 'Jaune vif aux UV.', 'Prismes quadratiques trapus, tablettes.', 'Zone d''oxydation des gisements de plomb, scories antiques au contact de l''eau de mer (Laurion, Grèce).', 'Du phosgène (COCl₂), dont elle contient les éléments.', null, 'Cérusite : orthorhombique, effervescente. Anglésite : sans chlore, analyse nécessaire.', 'Chlorocarbonate de plomb, dense et adamantin, fluorescent jaune ; on le trouve aussi dans les scories romaines.', 'published'),
  ('Platine', 'platine', 'Pt', 'Cubique', 'Éléments natifs', 4.0, 4.5, 14.0, 19.0, array['gris blanc acier','gris argent']::text[], 'métallique', 'aucun', 'gris acier brillant', 'opaque', 'crochue', null, 'Grains et pépites roulés dans les alluvions ; cubes très rares.', 'Roches ultrabasiques (dunites) et placers qui en dérivent (Oural, Colombie, Afrique du Sud).', 'De l''espagnol platina (petit argent).', 'Polyxène (platine ferrifère).', 'Argent natif : plus léger, ternit en noir. Iridosmine : plus dure, analyse nécessaire.', 'Métal noble natif, malléable et très dense, souvent allié au fer, parfois légèrement magnétique.', 'published'),
  ('Sénarmontite', 'senarmontite', 'Sb₂O₃', 'Cubique', 'Oxydes et hydroxydes', 2.0, 2.5, 5.2, 5.5, array['incolore','blanc','gris']::text[], 'adamantin à résineux', 'indistinct', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Octaèdres nets, croûtes.', 'Altération de la stibine et de l''antimoine natif (Djebel Hamimat, Algérie).', 'De Henri Hureau de Sénarmont (1808-1862), minéralogiste et physicien français.', null, 'Valentinite : même formule, orthorhombique, en prismes. Fluorite : clivage octaédrique net.', 'Oxyde d''antimoine en octaèdres blancs, dédié à un minéralogiste français.', 'published'),
  ('Sépiolite', 'sepiolite', 'Mg₄Si₆O₁₅(OH)₂·6H₂O', 'Orthorhombique', 'Silicates (phyllosilicates)', 2.0, 2.5, 2.0, 2.1, array['blanc','crème','gris']::text[], 'terreux, mat', 'aucun (visible)', 'blanc', 'opaque', 'conchoïdale à terreuse', null, 'Masses compactes poreuses et légères, nodules ; sèche, elle peut flotter.', 'Altération de serpentinites et de magnésite, bassins sédimentaires (Eskişehir, Turquie).', 'Du grec sêpion (os de seiche), léger et poreux.', 'Écume de mer (masses compactes taillées en pipes).', 'Magnésite : plus dure, effervescente à chaud. Kaolinite : plus dense, toucher gras.', 'Argile fibreuse si légère et poreuse qu''elle flotte : l''« écume de mer » des pipes sculptées.', 'published'),
  ('Skuttérudite', 'skutterudite', 'CoAs₃', 'Cubique', 'Sulfures et sulfosels', 5.5, 6.0, 6.1, 6.9, array['blanc d''étain','gris argent']::text[], 'métallique', 'indistinct', 'noir', 'opaque', 'conchoïdale à irrégulière', null, 'Cubes et cubo-octaèdres, masses granulaires ; se ternit en gris ou irisé.', 'Filons hydrothermaux à cobalt-nickel-argent (Bou Azzer, Maroc ; Skuterud, Norvège).', 'De Skuterud (Modum, Norvège).', 'Smaltite et chloanthite (anciens noms des termes riches en arsenic ou en nickel).', 'Cobaltite : rosée, clivage cubique. Arsénopyrite : prismes, odeur d''ail au choc.', 'Arséniure de cobalt blanc d''étain, minerai de cobalt dont l''altération donne l''érythrite rose.', 'published'),
  ('Stannite', 'stannite', 'Cu₂FeSnS₄', 'Quadratique', 'Sulfures et sulfosels', 3.5, 4.0, 4.3, 4.5, array['gris acier','noir à reflet olive']::text[], 'métallique', 'indistinct', 'noir', 'opaque', 'irrégulière', null, 'Masses granulaires ; cristaux pseudo-octaédriques rares.', 'Filons hydrothermaux à étain (Cornouailles, Bolivie).', 'Du latin stannum (étain).', null, 'Tétraédrite et tennantite : sans étain, éclat semblable. Chalcopyrite : jaune laiton.', 'Sulfure de cuivre, fer et étain gris acier, surnommé « étain pyriteux » ; secondaire comme minerai d''étain.', 'published'),
  ('Strengite', 'strengite', 'FePO₄·2H₂O', 'Orthorhombique', 'Phosphates, arséniates et vanadates', 3.5, 3.5, 2.8, 2.9, array['violet pâle','rose','incolore']::text[], 'vitreux', 'bon', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Sphérules et croûtes fibroradiées, petits cristaux.', 'Pegmatites à phosphates altérées, gisements de fer (Limousin, Bavière).', 'De Johann August Streng (1830-1897), minéralogiste allemand.', null, 'Variscite : pôle aluminium, vert. Phosphosidérite : monoclinique, analyse nécessaire.', 'Phosphate de fer rose violacé en petites sphères, pendant ferrifère de la variscite.', 'published'),
  ('Sugilite', 'sugilite', 'KNa₂(Fe,Mn,Al)₂Li₃Si₁₂O₃₀', 'Hexagonal', 'Silicates (cyclosilicates)', 5.5, 6.5, 2.7, 2.8, array['violet','pourpre','rose violacé']::text[], 'vitreux à cireux', 'faible', 'blanc', 'translucide à opaque', 'conchoïdale à irrégulière', null, 'Masses compactes ; cristaux très rares.', 'Gisements de manganèse métamorphisés (Wessels, Kalahari, Afrique du Sud) ; décrite au Japon.', 'De Ken-ichi Sugi (1901-1948), pétrologue japonais.', null, 'Charoïte : fibres soyeuses en volutes. Améthyste : plus dure, cristallisée.', 'Cyclosilicate violet intense, taillé en cabochons et perles ; il doit sa couleur au manganèse.', 'published'),
  ('Tennantite', 'tennantite', 'Cu₁₂As₄S₁₃', 'Cubique', 'Sulfures et sulfosels', 3.0, 4.5, 4.6, 4.7, array['gris acier','noir']::text[], 'métallique', 'aucun', 'noir à brun rouge', 'opaque', 'irrégulière à subconchoïdale', null, 'Tétraèdres nets, masses compactes.', 'Filons hydrothermaux de cuivre, plomb et zinc.', 'De Smithson Tennant (1761-1815), chimiste anglais.', 'Binnite (ancien nom, Binntal en Suisse).', 'Tétraédrite : pôle à antimoine de la série, analyse nécessaire. Énargite : clivage parfait.', 'Sulfoarséniure de cuivre en tétraèdres gris acier, pôle arsénié de la série de la tétraédrite.', 'published'),
  ('Thomsonite', 'thomsonite', 'NaCa₂Al₅Si₅O₂₀·6H₂O', 'Orthorhombique', 'Silicates (tectosilicates)', 5.0, 5.5, 2.2, 2.4, array['blanc','rosé','vert','incolore']::text[], 'vitreux à nacré', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière à subconchoïdale', null, 'Sphères et masses radiées, prismes en éventail ; nodules à zones concentriques colorées.', 'Cavités de basaltes (Lac Supérieur, Écosse, Féroé).', 'De Thomas Thomson (1773-1852), chimiste écossais.', 'Lintonite (verte), nodules « œil » du Lac Supérieur.', 'Natrolite : prismes plus fins. Prehnite : plus dure, vert pâle.', 'Zéolite en sphères radiées ; les nodules zonés du lac Supérieur se polissent comme des gemmes.', 'published'),
  ('Ulexite', 'ulexite', 'NaCaB₅O₆(OH)₆·5H₂O', 'Triclinique', 'Borates', 2.5, 2.5, 1.9, 2.0, array['blanc','incolore']::text[], 'soyeux à vitreux', 'parfait', 'blanc', 'transparent à opaque', 'irrégulière', 'Parfois jaune verdâtre à crème.', 'Masses fibreuses parallèles ; « boules de coton » dans les sédiments.', 'Évaporites des lacs salés et dépôts de borates (Californie, Turquie, Argentine).', 'De Georg Ludwig Ulex (1811-1883), chimiste allemand.', '« Pierre télévision » (fibres parallèles qui transmettent l''image).', 'Gypse fibreux (satin spar) : plus tendre, ne « transmet » pas l''image.', 'Borate fibreux surnommé « pierre télévision » : ses fibres agissent comme des fibres optiques et font remonter l''image.', 'published'),
  ('Valentinite', 'valentinite', 'Sb₂O₃', 'Orthorhombique', 'Oxydes et hydroxydes', 2.5, 3.0, 5.6, 5.8, array['incolore','blanc','jaunâtre','gris']::text[], 'adamantin, nacré sur clivage', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Prismes et tablettes en gerbes, rosettes, éventails.', 'Altération de la stibine et de l''antimoine natif.', 'De Basile Valentin, alchimiste légendaire auteur d''écrits sur l''antimoine.', null, 'Sénarmontite : même formule, cubique en octaèdres. Stibiconite : jaune, terreuse.', 'Oxyde d''antimoine en gerbes blanches nacrées, compagnon fréquent de la stibine altérée.', 'published'),
  ('Pharmacolite', 'pharmacolite', 'CaHAsO₄·2H₂O', 'Monoclinique', 'Phosphates, arséniates et vanadates', 2.0, 2.5, 2.5, 2.7, array['blanc','incolore','rosé (cobalt)']::text[], 'vitreux, soyeux en touffes, nacré sur clivage', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Aiguilles soyeuses en houppes, croûtes botryoïdales, efflorescences.', 'Altération des arséniures dans les anciennes galeries, souvent après l''exploitation ; classique à Sainte-Marie-aux-Mines (Haut-Rhin).', 'Du grec pharmakon (poison) et lithos (pierre).', null, 'Pikropharmacolite : contient du magnésium, analyse nécessaire. Gypse fibreux : sans arsenic, plus tendre.', 'Arséniate de calcium en houppes blanches soyeuses, emblématique des vieilles mines d''argent d''Alsace. Contient de l''arsenic : se laver les mains.', 'published'),
  ('Mixite', 'mixite', 'BiCu₆(AsO₄)₃(OH)₆·3H₂O', 'Hexagonal', 'Phosphates, arséniates et vanadates', 3.0, 4.0, 3.6, 3.8, array['vert émeraude','vert bleu']::text[], 'vitreux à soyeux', 'aucun', 'vert pâle', 'translucide', 'irrégulière', null, 'Aiguilles très fines en touffes radiées, enduits veloutés.', 'Zone d''oxydation des gisements de cuivre et bismuth arséniés : Cap Garonne (Var), Sainte-Marie-aux-Mines (Haut-Rhin).', 'D''Anton Mixa, responsable des mines de Jáchymov (Bohême).', null, 'Agardite : pôle à terres rares de la série, analyse nécessaire. Malachite : effervescente à l''acide.', 'Arséniate de cuivre et bismuth en houppes d''aiguilles vertes, recherché par les micromonteurs de Cap Garonne.', 'published'),
  ('Cyanotrichite', 'cyanotrichite', 'Cu₄Al₂(SO₄)(OH)₁₂·2H₂O', 'Orthorhombique', 'Sulfates, chromates, molybdates et tungstates', 1.0, 3.0, 2.7, 2.95, array['bleu ciel','bleu azur']::text[], 'soyeux', 'indistinct', 'bleu pâle', 'translucide', 'irrégulière', null, 'Touffes et enduits veloutés d''aiguilles capillaires.', 'Zone d''oxydation des gisements de cuivre ; Cap Garonne (Var) est une localité classique.', 'Du grec kyanos (bleu) et thrix (cheveu).', 'Lettsomite (ancien nom).', 'Carbonate-cyanotrichite : analyse nécessaire. Aurichalcite : bleu vert pâle, effervescente.', 'Sulfate de cuivre et aluminium en velours bleu ciel, l''un des plus beaux minéraux de Cap Garonne.', 'published'),
  ('Langite', 'langite', 'Cu₄(SO₄)(OH)₆·2H₂O', 'Monoclinique', 'Sulfates, chromates, molybdates et tungstates', 2.5, 3.0, 3.3, 3.5, array['bleu','bleu vert']::text[], 'vitreux à soyeux', 'parfait', 'bleu pâle', 'translucide', 'irrégulière', null, 'Petits cristaux tabulaires, croûtes et enduits.', 'Zone d''oxydation des gisements de cuivre ; souvent formée sur les parois des galeries après l''exploitation.', 'De Viktor von Lang (1838-1921), minéralogiste autrichien.', null, 'Posnjakite et wroewolfeite : même formule, analyse nécessaire. Brochantite : verte.', 'Sulfate de cuivre hydraté bleu, fréquent en petits cristaux dans les anciennes mines de cuivre françaises.', 'published'),
  ('Connellite', 'connellite', 'Cu₁₉Cl₄(SO₄)(OH)₃₂·3H₂O', 'Hexagonal', 'Halogénures', 3.0, 3.0, 3.3, 3.4, array['bleu azur intense']::text[], 'vitreux', 'aucun', 'bleu pâle', 'translucide', 'irrégulière', null, 'Aiguilles capillaires en rayons et touffes.', 'Zone d''oxydation des gisements de cuivre (Cornouailles ; Cap Garonne, Var).', 'D''Arthur Connell (1794-1863), chimiste écossais.', null, 'Cyanotrichite : bleu plus pâle, velours. Buttgenbachite : analyse nécessaire.', 'Chlorosulfate de cuivre en aiguilles d''un bleu électrique, rare et très prisé en micromontage.', 'published'),
  ('Devilline', 'devilline', 'CaCu₄(SO₄)₂(OH)₆·3H₂O', 'Monoclinique', 'Sulfates, chromates, molybdates et tungstates', 2.5, 2.5, 3.1, 3.2, array['vert émeraude','vert bleu']::text[], 'vitreux, nacré sur clivage', 'parfait', 'vert pâle', 'translucide', 'irrégulière', null, 'Rosettes de lamelles très minces, croûtes.', 'Zone d''oxydation des gisements de cuivre.', 'D''Henri Sainte-Claire Deville (1818-1881), chimiste français.', null, 'Serpierite : bleu ciel, contient du zinc. Langite : bleue, sans calcium.', 'Sulfate de calcium et cuivre en rosettes vertes nacrées, dédié à un chimiste français.', 'published'),
  ('Serpierite', 'serpierite', 'Ca(Cu,Zn)₄(SO₄)₂(OH)₆·3H₂O', 'Monoclinique', 'Sulfates, chromates, molybdates et tungstates', 2.0, 2.5, 3.0, 3.1, array['bleu ciel']::text[], 'vitreux à nacré', 'parfait', 'bleu pâle', 'translucide', 'irrégulière', null, 'Petites lattes en rosettes, croûtes.', 'Zone d''oxydation des gisements cuivre-zinc, scories antiques (Laurion, Grèce) ; présente à Cap Garonne (Var).', 'De Giovanni Battista Serpieri (1832-1897), exploitant des mines du Laurion.', null, 'Devilline : verte, sans zinc. Cyanotrichite : velours d''aiguilles.', 'Sulfate de cuivre, zinc et calcium en petites rosettes bleu ciel, classique en micromontage.', 'published'),
  ('Quincyte', 'quincyte', 'SiO₂·nH₂O', 'Amorphe', 'Oxydes et hydroxydes', 5.5, 6.0, 1.9, 2.2, array['rose','rose carmin','rose brun']::text[], 'cireux à terne', 'aucun', 'blanc', 'opaque à translucide', 'conchoïdale', null, 'Rognons et masses compactes dans les argiles.', 'Argiles et calcaires lacustres du Berry : Quincy et Mehun-sur-Yèvre (Cher).', 'De Quincy (Cher).', 'Variété rose d''opale commune.', 'Calcédoine rose : plus dure et plus dense. Rhodonite : bien plus dense, veines noires.', 'Opale rose du Berry, variété française rare ; l''origine de sa couleur (pigment organique ou argile) est discutée.', 'published'),
